<script setup>
import {safe} from '../presenter.js';
defineProps({timeline:{type:Object,default:()=>({})},compact:Boolean,simple:Boolean});
const fields=[['TC','tc'],['MIDI','midi'],['OSC','osc'],['NOTES','notes']];
</script>
<template><div :title="`Transport: ${safe(timeline.transportName)} · Track: ${safe(timeline.trackName)}`"><template v-if="compact"><span class="transport-label">{{safe(timeline.transportName)}}</span><span class="transport-divider" aria-hidden="true">{{' / '}}</span><span class="transport-name">{{safe(timeline.trackName)}}</span></template><template v-else-if="simple"><span class="transport-label">Track:</span><span class="transport-name">{{safe(timeline.trackName)}}</span></template><template v-else><div class="transport-id"><div v-for="field in [['Transport','transportName'],['Track','trackName']]" :key="field[1]" class="transport-line" :class="{'track-line':field[1]==='trackName'}"><span class="transport-label">{{field[0]}}:</span><span class="transport-name">{{safe(timeline[field[1]])}}</span></div></div><div class="section-cards"><div v-for="(section,index) in [timeline.currentSection,timeline.nextSection]" :key="index" class="section-card" :class="{'is-next':index===1}" :title="safe(section?.name)"><div class="section-caption"><div>{{index?'Next':'Current'}}</div><div>Section</div></div><div class="section-fields"><div v-for="field in fields" :key="field[1]" class="section-field" :data-field="field[1]"><span class="section-field-label">{{field[0]}}</span><span class="section-value" :title="field[1]==='osc'?'CUE tag for OSC: '+safe(section?.[field[1]]):safe(section?.[field[1]])">{{safe(section?.[field[1]])}}</span></div></div></div></div></template></div></template>
